import logging
import time
import sys
import os

FORMAT = "[%(asctime)s - %(levelname)s] - [%(filename)s:%(lineno)s %(funcName)s()] -  %(message)s"
DATE_FORMAT='%m/%d/%Y %I:%M:%S %p'


def useLogging(log_level=logging.INFO):
    date_time = time.strftime("%d%m%Y_%H%M%S%p")
    log_directory = fr"{os.path.expanduser('~')}\interops_logs"

    if not os.path.exists(log_directory):
        os.makedirs(log_directory)

    log_file = fr"{log_directory}\interops_{date_time}.log"
    logging.basicConfig(filename=log_file, level=log_level, format=FORMAT, datefmt=DATE_FORMAT, force=True)
    logging.info('Start of log file at ' + time.strftime("%d%m%Y-%H%M%S%p"))


def logToConsole(log_level=logging.DEBUG):
    console_format = "- %(levelname)s - [%(filename)s:%(lineno)s %(funcName)s()] -  %(message)s"

    root = logging.getLogger()
    root.setLevel(log_level)
    handler = logging.StreamHandler(sys.stdout)
    handler.setLevel(log_level)
    formatter = logging.Formatter(console_format)
    handler.setFormatter(formatter)
    root.addHandler(handler)